WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (395::BIGINT, 'Se sabe que ca es bastante complicado, igualmente siento que el profe explica bastante bien y hace preguntas para que el estudiante participe de la solución de los ejercicios, pero es cierto que califica DEMASIADO duro.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, '80c425667eb2b1b97593acac79d9e0eb03fd8106df60ca7bdd6512c75d57e80f'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Es buen profe, explica bien, pocas son las veces donde no se le entiende algo. No se si será solo en CA pero califica extremadamente rudo, si usted se equivocó en una parte del procedimiento de ahí para abajo es 0. CA es un curso bastante pesado. A la hora de evaluar William es un Barbosa, binario.'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2026-06-29T00:00:00+00:00'::TIMESTAMPTZ, '5b49dc4cde8f6810d391bc783e255862d008633072d3d9610db6b45050e3eea5'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Sin duda uno de los mejores profesores de la escuela. Las clases pueden ser algo aburridas, pero el profesor sabe mucho y explica muy bien, se le nota la vocación. Excelente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, '7427dde34528d65da1828b1c606aae3f3c5c12a6d51bbdcf1033ac8f8a5dd925'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'La mejor opción para CA. Explica bien, hace pocos ejemplos pero los explica a profundidad y este semestre fue el profe que hizo las actividades menos rudas. Lo único malo puede ser el horario, que hable muy bajo o la poca cantidad de ejercicios que resuelve'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '89c283b9bd31a7e70fa726a79ed42b97956e00e6837f10fec9a9a0796d851c32'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Por mucho la mejor opción para llevar CA, hace que el curso sea un poco más llevadero. Explica súper claro todos los temas y califica normal. El curso es duro e igual demanda poner de su parte, lo mejor es aprovechar las tutorías para obligarse a estar practicando y así ir más preparado al examen'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2025-12-07T00:00:00+00:00'::TIMESTAMPTZ, '0060c8c775a64ee414b3de67d1d544dc564f853445f6d59b73558d7b9847912a'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Cuesta mucho entenderle en clase, habla muy bajito entonces al inicio cuesta mucho prestarle atención. En general, es buena gente y califica normal, pero CA de por sí es un curso complicado.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2025-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'f74be3034de5658ccd05e671e5b1fc280e3595f857744c96582f1fc128af61a4'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Lo bueno es que califica justo en los exámenes, y para un curso como CA es más que necesario. Sus clases se entienden si pones mucha atención, no hace muchos ejercicios, pero con las tutorías eso se resuelve. Habla muy bajito y si te sientas atrás te cuesta mucho entender, pero es el mejor para CA'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'c790afa93edd767f768c73f1d5bc412e3d01818fd63e92b4e02109aee74e43bd'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Muy buen profe, califica de manera justa en los examenes. CA es un curso muy denso pero con práctica se logra pasar. Si lleva tutorias, se obliga a estudiar más y llevar la materia al día haciendo el curso ligeramente menos pesado. En clase el profe trata de explicar de la mejor manera.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '8ad989b3f9af782304af4b3209d3f82d9deb0a379340dacba64be7c950594e92'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Es un profe justo, no regala nada pero califica de una manera justa. CA necesita de mucha práctica y ser algo autodidáctico también, el profe explica bastante bien y es muy buena gente.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, 'f46e1aac57b465c49405d857e198bb8d0c5566fb94ea2c041c0516c1042764b3'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Es una clase organizada y muy pesada, el profesor es excelente en consulta y nunca toma las dudas en contra del estudiante. Sus quices son razonables y normalmente del mismo nivel que los ejercicios simples de la bibliografía.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2024-05-27T00:00:00+00:00'::TIMESTAMPTZ, 'd4ff905cd1170084ef30897d1a3999328e98a0fbbcf467a234f1fd81aa916ae4'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Es un gran profe. Explica muy bien, los ejemplos son bastantes claros, ayuda en la medida de lo posible y ayuda mucho en consulta.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-29T00:00:00+00:00'::TIMESTAMPTZ, '8ba70ef8e5390dc296849939c70d996cd254675918cd3008c87945096933bbae'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'El mejor profe para CA. No califica binario, explica muy bien en las clases, hace buenos ejercicios y en consulta ayuda bastante. En los examenes si se dispone a ayudarlo a uno con dudas en ves de salir con el "no se, se me olvido". Super recomendado'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '98ed7a9e79fcfcdfa69683a3f16e853544778889d1578ee7520c4d063578cfc4'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'En tem2 es la opción que hay que elegir, explica muy bien, deja quices razonables y hace muchos ejercicios en clase. Super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '85120fa4f8881eb112a010445feb30802477ba55d83922eb245d4f86f957ed38'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Explica bien, a veces se hace enreda pero nada extremo. No revisa binario, da puntos por procedimiento y la curva ayuda mucho. Si tiene dudas el explica de nuevo, hasta que uno entienda, es muy respetuoso y puntual. Lo que no me gustó fue cuando dejó videos (dan sueño).'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Exámenes retadores']::TEXT[], '2022-11-27T00:00:00+00:00'::TIMESTAMPTZ, '328ae5b69c9315c9aa531ee68c5a42434e44235e6ab4e819129a5d745704daf9'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Buen profesor, resuelve bastantes ejercicios en clase (lo cual es bueno, porque a veces en este curso los profes se atienen a que ejercicios, nada mas lo que se ve en la tutoría) califica normal, quices razonables y en general, recomendadísimo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-25T00:00:00+00:00'::TIMESTAMPTZ, '346cf4b640aea18442a7bc2ac728ee2347da2e3d981f243b2d1895b9b75a1d17'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Es buen profesor, los quices son sencillos, las tareas también, los exámenes lo hacen entre los profes que dan el curso, pero uno va bien preparado, además califica suave. Promete.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'a515b068a6b4a9553e13a476b2cc90ba0c1bda249118629c306a181d8b06f261'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'El curso ya es complicado y los exámenes catedráticos son demasiado difíciles. El profe explica muy bien la materia pero es necesario estudiar mucho más por cuenta propia para salir bien. Es justo calificando (no es binario) y las clases son un poco aburridas.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('60','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'bf6312ed13cf55862333a56ecac7b1ec490696a8b430d59a6e00c14f4ccb32ad'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Profe buena nota , explica bien y claro . Explica mediante presentaciones. Los quices no son nada del otro mundo y las tareas es hacer formularios para los examenes. Los examenes lo hacen entre los 3 profes pero es pasable, el profe califica suave. Aveces no responde correos'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'ebd8bf43deeaabfede9318a89eb31a19ace497df85471f77701735f2f6ce32ce'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Es muy buen profesor, explica los temas de manera que sean comprensibles e intuitivos, no entra en demasiada profundidad en el análisis matemático para dar pie a la parte más interesante. Los exámenes son los mismos para todos los profes, pero los califica relativamente suave. El curso es pasable.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '96d924dec2739a11e57f4fc774ffc7759d8d43e4db40d108c7229f110074881d'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Explica muy bien, hace ejercicios de exámenes pasados que sirve mucho de practica, sin embargo, no alcanza, tiene que practicar muchísimo por su cuenta. Califica normal.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Exámenes retadores']::TEXT[], '2021-12-08T00:00:00+00:00'::TIMESTAMPTZ, '9d5a08b87d586918cb9c45009a123ffb1981f74c97881d7f47697a29e54c1707'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, '16 tareas que aveces llevaban horas pero servía como práctica, los exámenes son de 5 horas y una evaluación que claramente busca joder al estudiante, pero bueno, así son los 3 profes por la "cátedra" que se inventaron, solo dió la mitad de clases sincrónicas como mucho, ser autodidacta para pasar.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'fe0286644527a97cd5e9ccb1525fb6f37204b1d6eaee5cc2ae64970f995cb6b7'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Es bueno explicando, hace varios ejemplos de exámenes de semestres anteriores que ayudan mucho. Sin embargo, dió muchas clases grabadas y es difícil aclarar dudas. Las tareas no son complicadas. La evaluación de los exámenes es muy difícil, hacen curva pero deberían ayudar más.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '719ddfcfed25d2564bf8e8985f99e87b2fb4e9701e2877b3ae2b78dc827a6531'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Literalmente el hace lo que Barboza le dice, se "inventaron" una cátedra para el curso donde no importa lo que usted marcó en examen sino su procedimiento, dió muy pocas clases y las que dio mejor no ir. Con él, el curso se vuelve autodidacta y si no le pone, con la evaluación no lo va a lograr.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '1f5328c32b6ce3e99aeb4cf8e6d4076be5b63808ea1f49b3d3cbb7a3c623c69c'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Esos bastardos me mintieron Para la modalidad virtual el otro profe fue mejor, calificando, haciendo curvas y los quices eras más sencillos, además las tutorías eran puntos extras, por dicha Anibal tiene todas sus clases en YT Me dijeron q era mejor, tal vez si lo que busca es la cura del insomnio'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Clases largas', 'Exámenes retadores']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'becb2a09631a7231f8a9185f3852bee46d0e688c204d55e5e23f299f6a31fc90'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Las explicaciones que da en sí son buenas y claras, pero como profe al menos en virtual es muy vago, solo dio menos de la mitad de las clases las otras subía videos en muy mala calidad y plataforma, tareas semanales largas, tiene que poner mucho d su parte para el examen no basta con las clases'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'f03db4bfd784c95661b5e8f40af8085635b93d80e34bacd24c385fa28f2b55d3'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'No, por favor.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('30','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '834fcbb73b29f18f8bfc7315d486e959d6ea561f731211be7612e22f8eaf46bc'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Buen profe, se enfoca en dar un explicacion sobre la materia y todo lo demas es practica por lo que ayuda bastante'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, '3ec6679fa3f84f23444bf3fa044d34a64f8d1aa7ce59f5479ee13e0fdcee7432'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Si quiere matricular TEM 2, este porfe es el mejor. Hay que madrugar porque da las clases a las 7:30 am oero lo vale.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, '93b1c0f1a4b35d60f6478ffb9eaf25881c4ac4b08d7382e3c2344d802ab5e23f'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Explica bastante bien, siempre resuelve las dudas de los estudiantes y realiza algunos ejercicios que son bastante útiles. Es amable y respetuoso. El curso es bastante pesado, pero el profe califica justo, da puntos por procedimiento.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '00443c7a0dad0a5f7ea44ce132ef93faf9e5dffa126f33a7c10450eb6a8ce8a6'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'El profe es muy buena gente, explica muy bien y no se desespera por dar la materia en carrera. Hace varios ejemplos de examenes anteriores lo cual resulta muy util. Recomendado'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '7632d76f3a9922e9dda3c0b2794096348239fdf64970eb4c4079d5fd2a6b92d5'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'Excelente profesor, explica lento pero intenta dar la materia lo más clara que se puede, da muchos ejemplos de la vida real. No califica duro, da puntos por procedimiento, hace curva en los exámenes y los quices son normales. Recomiendo llevar la materia al día y si se puede asistir a las tutorías.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '6910b77a5593a069035a683a387bc24f3f106b77647daf16f13cac6d74418ece'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'El profe es nuevo, sin embargo es muy paciente y explica todas las veces que sean necesarias, el problema es que suele hacer ejercicios mucho más fáciles que los del examen, por lo que hay que practicar bastante por aparte y consultarle las dudas. Califica binario pero es por decisión de la cátedra.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2020-09-08T00:00:00+00:00'::TIMESTAMPTZ, '35bdbe209ea44cb1470cefdd8503f9bbf66c149219cf735593f5612ac0233900'::TEXT, ARRAY[1262]::BIGINT[]),
    (395::BIGINT, 'En su primer clase paso menos del 20%, aburrido, pasa la mayoría de la clase balbuceando. Cuando se le pregunta sobre un tema recomiende ver los vídeos de otro profesor en lugar de ayudar al estudiante. 2 exámenes de alto porcentaje, marque con x que requiere justificación pero califica binariament'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, '675a31ee254c526841413b0cc295b6ed3534e9c504f4284c83b2e94ff4ef2b68'::TEXT, ARRAY[1296]::BIGINT[]),
    (395::BIGINT, 'Es un buen profe. Explica MUY lento y utiliza tableta gráfica para explicar. Da puntos por procedimiento y hace curva. Es mejor estudiar conforme se va avanzando en la materia para no perderse en sus clases. Quices normales y es muy paciente.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-21T00:00:00+00:00'::TIMESTAMPTZ, '416dd4195a6e86eeb29db2cae5c27ba367e3ae1f3ec7fec23200a9074b8e723a'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'El profe es nuevo y por ende hay cosas que aun le faltan, pero en general es bueno. Hace bastantes quices, para que uno lleve la materia al dia. En los examenes ayuda, como son de catedra son dificiles, pero el profe no califica tan duro. Da puntos por procedimiento. Hace curva.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '5b8b8042263d142df4d212f395ad74065983d20291eca1c932b68f8db58ea276'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'No deje que se acumule la materia, haga un buen formulario y estudie en grupos.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Requiere mucha lectura', 'Clases largas']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '0be94c270c892dc8823939efd17ad171ac95ccabdae3a20240b1116ba138b571'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'El profe explicar todas las veces que sean necesarias, califica normal y hace curva de Gauss'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'a9ad57560770f250b86201c4cc6b70b829cb9f5750569f9d6958e2c4e14e8883'::TEXT, ARRAY[1307]::BIGINT[]),
    (395::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2020-08-03T00:00:00+00:00'::TIMESTAMPTZ, '27791bded3bff53dfeaf79807fdce0231acb3123a420cec8742f5ab5a6d70f8e'::TEXT, ARRAY[1262]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
